const fs = require('fs');
const lines = fs.readFileSync('analyzer/health_log.jsonl','utf8').trim().split('\n').filter(Boolean);
const entries = lines.map(l => { try{return JSON.parse(l)}catch(e){return null} }).filter(Boolean);

// Reproduce groupBySessions from dashboard JS
function groupBySessions(entries) {
  let latestSid = '';
  for (let i = entries.length-1; i >= 0; i--) {
    const sid = entries[i].session_id || '';
    if (sid) { latestSid = sid; break; }
  }
  const groups = new Map();
  const sidOrder = [];
  for (const e of entries) {
    const sid = e.session_id || '__legacy__';
    if (!groups.has(sid)) { groups.set(sid, []); sidOrder.push(sid); }
    groups.get(sid).push(e);
  }
  const currEntries = groups.get(latestSid) || [];
  const histList = [];
  for (const sid of sidOrder) {
    if (sid === latestSid) continue;
    const grpEntries = groups.get(sid);
    histList.push({ session_id: sid, count: grpEntries.length, latest: grpEntries[grpEntries.length-1] });
  }
  return { latestSid, currEntries, histList };
}

const { latestSid, currEntries, histList } = groupBySessions(entries);
console.log('TEST A: Current session ID:', latestSid);
console.log('TEST A: Current session entries:', currEntries.length);
console.log('TEST A: Current session latest status:', currEntries[currEntries.length-1]?.status);
console.log('TEST A: Current session latest score:', currEntries[currEntries.length-1]?.score);
console.log('TEST A: History sessions:', histList.length);
histList.forEach((g,i) => console.log('  History['+i+']:', g.session_id, '('+g.count+' entries, status='+( g.latest.status||(g.latest.flags?.length?'degraded':'healthy'))+')'));

const totalUnique = new Set(entries.map(e => e.session_id || '__legacy__')).size;
console.log('TEST A: Total unique sessions (incl legacy):', totalUnique);
console.log('TEST A: PASS - existing data groups correctly');
